    favorite           INTEGER NOT NULL DEFAULT 0
, genre_id INTEGER REFERENCES genres(id) ON DELETE SET NULL, genre_source TEXT CHECK (genre_source IN ('auto', 'manual')), feed_id INTEGER REFERENCES feeds(id) ON DELETE SET NULL, text_length INTEGER, difficulty INTEGER CHECK (difficulty BETWEEN 1 AND 5), difficulty_source TEXT CHECK (difficulty_source IN ('auto', 'manual')));

